def S(pts, mags={}): return [{'id': i, 'x': round(float(x), 1), 'y': round(float(y), 1), 'mag': mags.get(i, 1)} for i, x, y in pts]
def P(spec): return [tuple([t.split()[0]] + [float(v) for v in t.split()[1:]]) for t in spec.split(',')]
def E(txt): return [t.strip().split('-') for t in txt.split(',')]
def ring(pre, n, cx, cy, rx, ry, a0=0): return [(f'{pre}{k + 1}', cx + rx * math.cos(math.radians(a0 + 360 / n * k)), cy + ry * math.sin(math.radians(a0 + 360 / n * k))) for k in range(n)]
def B(i, name, desc, eff): return {'id': i, 'name': name, 'desc': desc, 'effects': [{'stat': k, 'value': v} for k, v in eff]}
