def chk(t, w):
    if '…' in t or re.search(r'(?<!\.)\.{3}(?!\.)', t): bad.append(w + ' 점 3 개: ' + t)
    for m in re.finditer(r'\.{2,}', t):
        n = len(m.group(0)); end = re.match(r'[」』)\]”’"\']*[?!]*\s*$', t[m.end():])
        if n != (7 if end else 4): bad.append(f'{w} 점 {n} 개: {t}')
    if '?!' in t or '!!' in t: bad.append(w + ' ?! / !!: ' + t)
